//! Handles stratification of Datalog programs

use petgraph::{algo, graphmap::DiGraphMap};
use std::collections::{HashMap, HashSet};
use std::slice::Iter;
use syn::Ident;

pub struct Strata {
    list: Vec<Vec<Ident>>,
    index: HashMap<Ident, usize>,
}

impl Strata {
    pub fn new(relations: HashSet<Ident>, dependencies: HashSet<(&Ident, &Ident)>) -> Self {
        if relations.is_empty() {
            return Strata {
                list: vec![],
                index: HashMap::new(),
            };
        }

        // Build a directed graph where edge from A to B means A depends on B
        let mut graph = DiGraphMap::new();

        // Add all nodes
        for rel in &relations {
            graph.add_node(rel);
        }

        // Add edges
        for (goal, fact) in &dependencies {
            graph.add_edge(goal, fact, ());
        }

        // Find SCCs using Tarjan's algorithm
        let sccs = algo::tarjan_scc(&graph);

        // Map each relation to its SCC index
        let mut rel_to_scc = HashMap::new();
        for (scc_idx, scc) in sccs.iter().enumerate() {
            for rel in scc {
                rel_to_scc.insert((*rel).clone(), scc_idx);
            }
        }

        // Build condensation graph (DAG of SCCs)
        let mut cond_graph = DiGraphMap::new();
        for i in 0..sccs.len() {
            cond_graph.add_node(i);
        }

        // Add edges in condensation graph
        let mut seen_edges = HashSet::new();
        for (goal, fact) in &dependencies {
            let goal_scc = rel_to_scc[&(**goal).clone()];
            let fact_scc = rel_to_scc[&(**fact).clone()];
            if goal_scc != fact_scc && !seen_edges.contains(&(goal_scc, fact_scc)) {
                cond_graph.add_edge(goal_scc, fact_scc, ());
                seen_edges.insert((goal_scc, fact_scc));
            }
        }

        // Topological sort the condensation graph
        let topo: Vec<_> = algo::toposort(&cond_graph, None)
            .expect("condensation graph should be acyclic")
            .into_iter()
            .collect();

        // Build topo_order: maps SCC index to its position in topological order
        let mut topo_order = vec![0; sccs.len()];
        for (pos, scc_idx) in topo.iter().enumerate() {
            topo_order[*scc_idx] = pos;
        }

        // Build the strata lists
        let mut list = vec![Vec::new(); sccs.len()];
        let mut index = HashMap::new();

        for (scc_idx, scc) in sccs.iter().enumerate() {
            let stratum = topo_order[scc_idx];
            for rel in scc {
                list[stratum].push(rel.clone());
                index.insert(rel.clone(), stratum);
            }
        }

        Strata { list, index }
    }

    pub fn iter(&self) -> Iter<'_, Vec<Ident>> {
        self.list.iter()
    }

    pub fn find_relation(&self, rel: &Ident) -> usize {
        *self.index.get(rel).expect("key not found in stratum index")
    }
}
EOF
